import { useState, useRef, useCallback, useEffect } from "react";
import * as XLSX from "xlsx";
import { initializeApp } from "firebase/app";

const SCHOOL_LOGO_URL = "data:image/png;base64,";

const LOGO_URL = "data:image/jpeg;base64,";

import { getFirestore, collection, doc, onSnapshot, setDoc, deleteDoc, updateDoc, getDocs, writeBatch } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "AIzaSyBBy8v9LRe_5UjROYFjHR5aTtmvzo6R1jk",
  authDomain: "girlguiding-nr.firebaseapp.com",
  projectId: "girlguiding-nr",
  storageBucket: "girlguiding-nr.firebasestorage.app",
  messagingSenderId: "506246287676",
  appId: "1:506246287676:web:44116dda0b9683e9b50e39"
};
const app = initializeApp(firebaseConfig);
const db = getFirestore(app);

const VIEW = { ADMIN: "admin", CHECKIN: "checkin", SUMMARY: "summary" };
const ADMIN_PASSWORD = "admin1234";
const EMPTY_FORM = { firstName: "", lastName: "", studentId: "", troop: "", grade: "", room: "" };
const FIELDS = [
  { key: "studentId", label: "เลขประจำตัว" },
  { key: "firstName", label: "ชื่อ" },
  { key: "lastName", label: "สกุล" },
  { key: "troop", label: "หมู่ผู้บำเพ็ญ" },
  { key: "grade", label: "ระดับชั้น" },
  { key: "room", label: "ห้อง" },
];

export default function ScoutAttendance() {
  const [view, setView] = useState(VIEW.CHECKIN);
  const [students, setStudents] = useState([]);
  const [attendance, setAttendance] = useState({});
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [searchResult, setSearchResult] = useState(null);
  const [confirmed, setConfirmed] = useState(null);
  const [activityDate, setActivityDate] = useState(new Date().toISOString().split("T")[0]);
  const [viewDate, setViewDate] = useState(new Date().toISOString().split("T")[0]);
  const unsubAttendanceRef = useRef(null);
  const [activityName, setActivityName] = useState("กิจกรรมผู้บำเพ็ญประโยชน์");
  const [dragOver, setDragOver] = useState(false);
  const [importError, setImportError] = useState("");
  const [adminPw, setAdminPw] = useState("");
  const [adminUnlocked, setAdminUnlocked] = useState(false);
  const [pwError, setPwError] = useState("");
  const [addForm, setAddForm] = useState(EMPTY_FORM);
  const [addError, setAddError] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editForm, setEditForm] = useState(EMPTY_FORM);
  const fileRef = useRef();

  // ── Real-time listeners ──
  useEffect(() => {
    const unsub1 = onSnapshot(collection(db, "students"), (snap) => {
      setStudents(snap.docs.map(d => ({ id: d.id, ...d.data() })));
      setLoading(false);
    });
    return () => { unsub1(); };
  }, []);

  // ── Listen to attendance by date ──
  useEffect(() => {
    if (unsubAttendanceRef.current) unsubAttendanceRef.current();
    const colName = "attendance_" + viewDate;
    const unsub = onSnapshot(collection(db, colName), (snap) => {
      const map = {};
      snap.docs.forEach(d => { map[d.id] = d.data(); });
      setAttendance(map);
    });
    unsubAttendanceRef.current = unsub;
    return () => unsub();
  }, [viewDate]);

  // ── Check-in ──
  const handleSearch = () => {
    setConfirmed(null);
    const q = search.trim().toLowerCase();
    if (!q) return;
    setSearchResult(students.filter(s =>
      s.studentId.includes(q) || s.firstName.toLowerCase().includes(q) || s.lastName.toLowerCase().includes(q)
    ));
  };
  const handleConfirmAttendance = async (s) => {
    const rec = { ...s, time: new Date().toLocaleTimeString("th-TH"), date: activityDate };
    await setDoc(doc(db, "attendance_" + activityDate, s.studentId), rec);
    setConfirmed(s);
    setSearch("");
    setSearchResult(null);
  };

  // ── Excel import ──
  const parseExcel = (file) => {
    setImportError("");
    const reader = new FileReader();
    reader.onload = async (e) => {
      try {
        const wb = XLSX.read(e.target.result, { type: "binary" });
        const rows = XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1 });
        const parsed = [];
        for (let i = 1; i < rows.length; i++) {
          const r = rows[i];
          if (!r || r.length < 5) continue;
          const [studentId, firstName, lastName, troop, grade, room] = r.map(c => String(c ?? "").trim());
          if (!studentId) continue;
          parsed.push({ firstName, lastName, studentId, troop, grade, room: room||"" });
        }
        if (!parsed.length) { setImportError("ไม่พบข้อมูลในไฟล์"); return; }
        const batch = writeBatch(db);
        parsed.forEach(s => batch.set(doc(db, "students", s.studentId), s));
        await batch.commit();
        alert(`นำเข้าสำเร็จ ${parsed.length} คน`);
      } catch(err) { setImportError("เกิดข้อผิดพลาด: " + err.message); }
    };
    reader.readAsBinaryString(file);
  };
  const handleFileDrop = useCallback((e) => { e.preventDefault(); setDragOver(false); const f = e.dataTransfer.files[0]; if (f) parseExcel(f); }, []);
  const handleFileInput = (e) => { const f = e.target.files[0]; if (f) parseExcel(f); };

  // ── Download ──
  const downloadTemplate = () => {
    const ws = XLSX.utils.aoa_to_sheet([["เลขประจำตัว","ชื่อ","สกุล","หมู่ผู้บำเพ็ญ","ระดับชั้น","ห้อง"],["6501001","สมหญิง","ใจดี","หมู่ 1 ดอกบัว","ม.1","1/1"]]);
    ws["!cols"] = [{wch:14},{wch:16},{wch:16},{wch:18},{wch:12},{wch:10}];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "นักเรียน");
    XLSX.writeFile(wb, "แบบฟอร์มนำเข้านักเรียน.xlsx");
  };
  const downloadReport = () => {
    const rows = [["เลขประจำตัว","ชื่อ","สกุล","หมู่ผู้บำเพ็ญ","ระดับชั้น","ห้อง","สถานะ","เวลาลงชื่อ","วันที่"]];
    students.forEach(s => { const r = attendance[s.studentId]; rows.push([s.studentId,s.firstName,s.lastName,s.troop,s.grade,s.room||"-",r?"มา":"ขาด",r?.time||"-",r?.date||viewDate]); });
    const ws = XLSX.utils.aoa_to_sheet(rows);
    ws["!cols"] = [{wch:16},{wch:16},{wch:14},{wch:18},{wch:12},{wch:8},{wch:12}];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "เช็คชื่อ");
    XLSX.writeFile(wb, `เช็คชื่อ_${activityName}_${activityDate}.xlsx`);
  };

  // ── Add student ──
  const handleAddStudent = async () => {
    const { firstName, lastName, studentId, troop, grade, room } = addForm;
    if (!firstName || !lastName || !studentId || !troop || !grade) { setAddError("กรุณากรอกข้อมูลให้ครบทุกช่อง"); return; }
    if (students.find(s => s.studentId === studentId)) { setAddError("เลขประจำตัวนี้มีอยู่แล้ว"); return; }
    await setDoc(doc(db, "students", studentId), { firstName, lastName, studentId, troop, grade, room: room||"" });
    setAddForm(EMPTY_FORM);
    setAddError("");
  };

  // ── Edit student ──
  const startEdit = (s) => { setEditingId(s.studentId); setEditForm({ firstName: s.firstName, lastName: s.lastName, studentId: s.studentId, troop: s.troop, grade: s.grade, room: s.room||"" }); };
  const saveEdit = async (oldId) => {
    const { firstName, lastName, studentId, troop, grade, room } = editForm;
    if (!firstName || !lastName || !studentId || !troop || !grade) return;
    if (studentId !== oldId && students.find(s => s.studentId === studentId)) { alert("เลขประจำตัวนี้มีอยู่แล้ว"); return; }
    if (studentId !== oldId) {
      await setDoc(doc(db, "students", studentId), { firstName, lastName, studentId, troop, grade, room: room||"" });
      await deleteDoc(doc(db, "students", oldId));
      if (attendance[oldId]) {
        await setDoc(doc(db, "attendance_" + viewDate, studentId), { ...attendance[oldId], studentId });
        await deleteDoc(doc(db, "attendance_" + viewDate, oldId));
      }
    } else {
      await updateDoc(doc(db, "students", oldId), { firstName, lastName, troop, grade, room: room||"" });
    }
    setEditingId(null);
  };

  // ── Delete student ──
  const deleteStudent = async (id) => {
    if (!confirm("ลบนักเรียนคนนี้?")) return;
    await deleteDoc(doc(db, "students", id));
    await deleteDoc(doc(db, "attendance_" + viewDate, id)).catch(() => {});
  };

  // ── Toggle attendance ──
  const toggleAttendance = async (s) => {
    if (attendance[s.studentId]) {
      await deleteDoc(doc(db, "attendance_" + viewDate, s.studentId));
    } else {
      await setDoc(doc(db, "attendance_" + viewDate, s.studentId), { ...s, time: new Date().toLocaleTimeString("th-TH") + " (Admin)", date: viewDate });
    }
  };

  // ── Reset attendance ──
  const resetAttendance = async () => {
    if (!confirm("ล้างข้อมูลการเช็คชื่อทั้งหมด?")) return;
    const snap = await getDocs(collection(db, "attendance_" + viewDate));
    const batch = writeBatch(db);
    snap.docs.forEach(d => batch.delete(d.ref));
    await batch.commit();
  };

  const present = students.filter(s => attendance[s.studentId]);
  const absent = students.filter(s => !attendance[s.studentId]);
  const pct = students.length ? Math.round(present.length / students.length * 100) : 0;
  const byTroop = {};
  students.forEach(s => { if (!byTroop[s.troop]) byTroop[s.troop] = { present: 0, total: 0 }; byTroop[s.troop].total++; if (attendance[s.studentId]) byTroop[s.troop].present++; });

  return (
    <div style={{ minHeight:"100vh", background:"linear-gradient(135deg,#0a1628 0%,#162040 50%,#0d2233 100%)", fontFamily:"'Sarabun','Noto Sans Thai',sans-serif", color:"#e8f4f8" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;500;600;700;800&display=swap');
        *{box-sizing:border-box;margin:0;padding:0;}
        ::-webkit-scrollbar{width:6px;} ::-webkit-scrollbar-track{background:rgba(255,255,255,.05);} ::-webkit-scrollbar-thumb{background:rgba(100,200,255,.3);border-radius:3px;}
        .badge{display:inline-block;padding:2px 10px;border-radius:20px;font-size:12px;font-weight:600;}
        .badge-present{background:rgba(34,197,94,.2);color:#4ade80;border:1px solid rgba(34,197,94,.3);}
        .badge-absent{background:rgba(239,68,68,.2);color:#f87171;border:1px solid rgba(239,68,68,.3);}
        .btn{padding:10px 20px;border-radius:10px;border:none;cursor:pointer;font-family:inherit;font-size:15px;font-weight:600;transition:all .2s;}
        .btn-primary{background:linear-gradient(135deg,#3b82f6,#0ea5e9);color:white;}
        .btn-primary:hover{transform:translateY(-1px);box-shadow:0 4px 20px rgba(59,130,246,.5);}
        .btn-success{background:linear-gradient(135deg,#22c55e,#16a34a);color:white;}
        .btn-success:hover{transform:translateY(-1px);box-shadow:0 4px 20px rgba(34,197,94,.5);}
        .btn-warning{background:linear-gradient(135deg,#f59e0b,#d97706);color:white;}
        .btn-warning:hover{transform:translateY(-1px);box-shadow:0 4px 20px rgba(245,158,11,.4);}
        .btn-ghost{background:rgba(255,255,255,.08);color:#94a3b8;border:1px solid rgba(255,255,255,.12);}
        .btn-ghost:hover{background:rgba(255,255,255,.15);color:#e2e8f0;}
        .card{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:16px;padding:20px;backdrop-filter:blur(10px);}
        .input-field{width:100%;padding:12px 16px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:10px;color:#e8f4f8;font-family:inherit;font-size:16px;outline:none;transition:border-color .2s;}
        .input-field:focus{border-color:#3b82f6;box-shadow:0 0 0 3px rgba(59,130,246,.15);}
        .input-field::placeholder{color:rgba(255,255,255,.3);}
        .input-sm{width:100%;padding:8px 10px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:8px;color:#e8f4f8;font-family:inherit;font-size:13px;outline:none;}
        .input-sm:focus{border-color:#3b82f6;}
        .input-sm::placeholder{color:rgba(255,255,255,.3);}
        .nav-btn{padding:8px 20px;border-radius:30px;border:none;cursor:pointer;font-family:inherit;font-size:14px;font-weight:600;transition:all .2s;}
        .nav-active{background:rgba(59,130,246,.25);color:#60a5fa;border:1px solid rgba(59,130,246,.4);}
        .nav-inactive{background:transparent;color:#64748b;border:1px solid transparent;}
        .nav-inactive:hover{color:#94a3b8;border-color:rgba(255,255,255,.1);}
        .result-card{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:12px;padding:14px 18px;transition:all .2s;cursor:pointer;}
        .result-card:hover{background:rgba(59,130,246,.15);border-color:rgba(59,130,246,.4);transform:translateY(-1px);}
        .confirm-banner{background:linear-gradient(135deg,rgba(34,197,94,.2),rgba(16,185,129,.15));border:1px solid rgba(34,197,94,.4);border-radius:16px;padding:20px;text-align:center;animation:fadeIn .4s ease;}
        @keyframes fadeIn{from{opacity:0;transform:translateY(-10px);}to{opacity:1;transform:translateY(0);}}
        .stat-card{background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);border-radius:14px;padding:18px;text-align:center;}
        .progress-bar{height:8px;background:rgba(255,255,255,.1);border-radius:4px;overflow:hidden;}
        .progress-fill{height:100%;border-radius:4px;background:linear-gradient(90deg,#22c55e,#84cc16);transition:width .8s ease;}
        table{width:100%;border-collapse:collapse;font-size:13px;}
        th{padding:10px 10px;text-align:left;background:rgba(255,255,255,.07);color:#94a3b8;font-weight:600;font-size:12px;}
        td{padding:8px 10px;border-bottom:1px solid rgba(255,255,255,.06);}
        tr:hover td{background:rgba(255,255,255,.03);}
        .tag{display:inline-block;padding:2px 8px;border-radius:6px;font-size:11px;background:rgba(99,102,241,.2);color:#a5b4fc;border:1px solid rgba(99,102,241,.3);}
        .drop-zone{border:2px dashed rgba(59,130,246,.4);border-radius:14px;padding:30px;text-align:center;transition:all .2s;cursor:pointer;}
        .drop-zone:hover,.drop-zone.over{border-color:#3b82f6;background:rgba(59,130,246,.1);}
        .add-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:10px;}
        .btn-sm{padding:4px 8px;border-radius:6px;border:none;cursor:pointer;font-size:13px;transition:all .15s;}
        .btn-edit{background:rgba(59,130,246,.2);color:#60a5fa;}
        .btn-edit:hover{background:rgba(59,130,246,.4);}
        .btn-del{background:rgba(239,68,68,.2);color:#f87171;}
        .btn-del:hover{background:rgba(239,68,68,.4);}
        .btn-save{background:rgba(34,197,94,.2);color:#4ade80;}
        .btn-save:hover{background:rgba(34,197,94,.4);}
        .btn-cancel{background:rgba(100,116,139,.2);color:#94a3b8;}
        .btn-cancel:hover{background:rgba(100,116,139,.4);}
        .edit-row td{background:rgba(59,130,246,.07);}
        .sync-dot{width:8px;height:8px;border-radius:50%;background:#4ade80;display:inline-block;margin-right:6px;animation:pulse 2s infinite;}
        @keyframes pulse{0%,100%{opacity:1;}50%{opacity:.4;}}
      `}</style>

      {/* Header */}
      <div style={{ background:"rgba(0,0,0,.3)", borderBottom:"1px solid rgba(255,255,255,.08)", padding:"12px 20px" }}>
        <div style={{ maxWidth:760, margin:"0 auto", display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:10 }}>
          <div style={{ display:"flex", alignItems:"center", gap:10 }}>
            <img src={LOGO_URL} alt="logo" style={{ width:40, height:40, borderRadius:"50%", objectFit:"cover", border:"2px solid rgba(255,255,255,.2)" }} />
            <div>
              <div style={{ fontWeight:700, fontSize:16, color:"#e2e8f0" }}>ระบบเช็คชื่อผู้บำเพ็ญประโยชน์โรงเรียนนางรอง</div>
              <div style={{ fontSize:12, color:"#64748b", display:"flex", alignItems:"center" }}>
                <span className="sync-dot" />
                <span>ซิงค์ Firebase · {activityDate}</span>
              </div>
            </div>
          </div>
          <div style={{ display:"flex", gap:6 }}>
            <button className={`nav-btn ${view===VIEW.CHECKIN?"nav-active":"nav-inactive"}`} onClick={() => setView(VIEW.CHECKIN)}>🔍 เช็คชื่อ</button>
            <button className={`nav-btn ${view===VIEW.SUMMARY?"nav-active":"nav-inactive"}`} onClick={() => setView(VIEW.SUMMARY)}>📊 สรุป</button>
            <button className={`nav-btn ${view===VIEW.ADMIN?"nav-active":"nav-inactive"}`} onClick={() => setView(VIEW.ADMIN)}>⚙️ จัดการ</button>
          </div>
        </div>
      </div>

      <div style={{ maxWidth:760, margin:"0 auto", padding:"20px 16px" }}>
        {loading && <div style={{ textAlign:"center", padding:40, color:"#64748b" }}>⏳ กำลังโหลดข้อมูล...</div>}

        {/* ── CHECK-IN ── */}
        {!loading && view===VIEW.CHECKIN && (
          <div>
            <div style={{ textAlign:"center", marginBottom:28 }}>
              <div style={{ display:"flex", justifyContent:"center", alignItems:"center", gap:24, marginBottom:8 }}>
                <img src={SCHOOL_LOGO_URL} alt="school logo" style={{ width:80, height:80, borderRadius:"50%", objectFit:"cover", border:"3px solid rgba(255,255,255,.2)", boxShadow:"0 4px 20px rgba(0,0,0,.3)" }} />
                <img src={LOGO_URL} alt="scout logo" style={{ width:80, height:80, borderRadius:"50%", objectFit:"cover", border:"3px solid rgba(255,255,255,.2)", boxShadow:"0 4px 20px rgba(0,0,0,.3)" }} />
              </div>
              <h1 style={{ fontSize:24, fontWeight:800, color:"#e2e8f0", marginBottom:4 }}>ยืนยันการเข้าร่วมกิจกรรม</h1>
              <p style={{ color:"#64748b", fontSize:15 }}>ค้นหาชื่อหรือเลขประจำตัวของคุณ แล้วกดยืนยัน</p>
            </div>

            {confirmed && (
              <div className="confirm-banner" style={{ marginBottom:20 }}>
                <div style={{ fontSize:36, marginBottom:8 }}>✅</div>
                <div style={{ fontSize:20, fontWeight:700, color:"#4ade80" }}>ลงชื่อเข้าร่วมสำเร็จ!</div>
                <div style={{ fontSize:18, marginTop:6, color:"#e2e8f0" }}>{confirmed.firstName} {confirmed.lastName}</div>
                <div style={{ fontSize:14, color:"#94a3b8", marginTop:4 }}>{confirmed.troop} · {confirmed.grade}</div>
              </div>
            )}

            <div className="card">
              <div style={{ display:"flex", gap:10 }}>
                <input className="input-field" placeholder="พิมพ์ชื่อ, นามสกุล หรือเลขประจำตัว..." value={search}
                  onChange={(e) => { setSearch(e.target.value); setSearchResult(null); setConfirmed(null); }}
                  onKeyDown={(e) => e.key==="Enter" && handleSearch()} style={{ flex:1 }} />
                <button className="btn btn-primary" onClick={handleSearch}>ค้นหา</button>
              </div>
              {searchResult !== null && (
                <div style={{ marginTop:14 }}>
                  {searchResult.length===0
                    ? <div style={{ textAlign:"center", padding:"20px", color:"#64748b" }}>ไม่พบชื่อหรือเลขประจำตัวนี้</div>
                    : <>
                        <div style={{ fontSize:13, color:"#64748b", marginBottom:10 }}>พบ {searchResult.length} รายการ — กดเลือกเพื่อยืนยัน</div>
                        <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                          {searchResult.map(s => {
                            const done = !!attendance[s.studentId];
                            return (
                              <div key={s.studentId} className="result-card" onClick={() => !done && handleConfirmAttendance(s)} style={{ opacity:done?.6:1, cursor:done?"default":"pointer" }}>
                                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                                  <div>
                                    <div style={{ fontWeight:700, fontSize:16, color:"#e2e8f0" }}>{s.firstName} {s.lastName}</div>
                                    <div style={{ fontSize:13, color:"#94a3b8", marginTop:3 }}>เลข {s.studentId} · <span className="tag">{s.troop}</span> · {s.grade}</div>
                                  </div>
                                  {done ? <span className="badge badge-present">✓ ลงชื่อแล้ว</span> : <span style={{ fontSize:22, color:"#3b82f6" }}>→</span>}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                      </>
                  }
                </div>
              )}
            </div>
            <div style={{ marginTop:20 }}>
              <div style={{ display:"flex", gap:12, marginBottom:12 }}>
                <div className="card" style={{ flex:1, textAlign:"center" }}><div style={{ fontSize:28, fontWeight:800, color:"#4ade80" }}>{present.length}</div><div style={{ fontSize:13, color:"#64748b" }}>มาแล้ว</div></div>
                <div className="card" style={{ flex:1, textAlign:"center" }}><div style={{ fontSize:28, fontWeight:800, color:"#f87171" }}>{absent.length}</div><div style={{ fontSize:13, color:"#64748b" }}>ยังไม่มา</div></div>
                <div className="card" style={{ flex:1, textAlign:"center" }}><div style={{ fontSize:28, fontWeight:800, color:"#60a5fa" }}>{students.length}</div><div style={{ fontSize:13, color:"#64748b" }}>ทั้งหมด</div></div>
              </div>
              {students.length > 0 && (() => {
                const byGrade = {};
                students.forEach(s => {
                  const g = s.grade || "ไม่ระบุ";
                  if (!byGrade[g]) byGrade[g] = { present:0, absent:0, total:0 };
                  byGrade[g].total++;
                  if (attendance[s.studentId]) byGrade[g].present++;
                  else byGrade[g].absent++;
                });
                const grades = Object.keys(byGrade).sort();
                return (
                  <div className="card" style={{ padding:"14px 16px" }}>
                    <div style={{ fontWeight:700, fontSize:14, marginBottom:10, color:"#94a3b8" }}>แยกตามชั้นเรียน</div>
                    <table style={{ width:"100%", borderCollapse:"collapse", fontSize:14 }}>
                      <thead>
                        <tr>
                          <th style={{ textAlign:"left", padding:"6px 10px", background:"rgba(255,255,255,.07)", color:"#94a3b8", fontSize:13 }}>ชั้น</th>
                          <th style={{ textAlign:"center", padding:"6px 10px", background:"rgba(255,255,255,.07)", color:"#4ade80", fontSize:13 }}>มาแล้ว</th>
                          <th style={{ textAlign:"center", padding:"6px 10px", background:"rgba(255,255,255,.07)", color:"#f87171", fontSize:13 }}>ยังไม่มา</th>
                          <th style={{ textAlign:"center", padding:"6px 10px", background:"rgba(255,255,255,.07)", color:"#60a5fa", fontSize:13 }}>ทั้งหมด</th>
                        </tr>
                      </thead>
                      <tbody>
                        {grades.map(g => (
                          <tr key={g}>
                            <td style={{ padding:"7px 10px", borderBottom:"1px solid rgba(255,255,255,.06)", fontWeight:600 }}>{g}</td>
                            <td style={{ padding:"7px 10px", borderBottom:"1px solid rgba(255,255,255,.06)", textAlign:"center", color:"#4ade80", fontWeight:700 }}>{byGrade[g].present}</td>
                            <td style={{ padding:"7px 10px", borderBottom:"1px solid rgba(255,255,255,.06)", textAlign:"center", color:"#f87171", fontWeight:700 }}>{byGrade[g].absent}</td>
                            <td style={{ padding:"7px 10px", borderBottom:"1px solid rgba(255,255,255,.06)", textAlign:"center", color:"#60a5fa", fontWeight:700 }}>{byGrade[g].total}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                );
              })()}
            </div>
          </div>
        )}

        {/* ── SUMMARY ── */}
        {!loading && view===VIEW.SUMMARY && (
          <div>
            <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16 }}>
              <h2 style={{ fontSize:20, fontWeight:700 }}>📊 สรุปการเข้าร่วมกิจกรรม</h2>
              <button className="btn btn-success" onClick={downloadReport} style={{ fontSize:13, padding:"8px 16px" }}>⬇️ Excel</button>
            </div>
            <div className="card" style={{ marginBottom:16, display:"flex", alignItems:"center", gap:12 }}>
              <span style={{ fontSize:14, color:"#94a3b8", whiteSpace:"nowrap" }}>📅 ดูวันที่:</span>
              <input className="input-field" type="date" value={viewDate} onChange={(e) => setViewDate(e.target.value)} style={{ flex:1 }} />
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:12, marginBottom:20 }}>
              <div className="stat-card"><div style={{ fontSize:32, fontWeight:800, color:"#4ade80" }}>{present.length}</div><div style={{ fontSize:13, color:"#64748b", marginTop:4 }}>มา</div></div>
              <div className="stat-card"><div style={{ fontSize:32, fontWeight:800, color:"#f87171" }}>{absent.length}</div><div style={{ fontSize:13, color:"#64748b", marginTop:4 }}>ขาด</div></div>
              <div className="stat-card"><div style={{ fontSize:32, fontWeight:800, color:"#60a5fa" }}>{pct}%</div><div style={{ fontSize:13, color:"#64748b", marginTop:4 }}>เข้าร่วม</div></div>
            </div>
            <div className="card" style={{ marginBottom:16 }}>
              <div style={{ display:"flex", justifyContent:"space-between", marginBottom:8 }}>
                <span style={{ fontSize:14, fontWeight:600 }}>ภาพรวมการเข้าร่วม</span>
                <span style={{ fontSize:14, color:"#4ade80" }}>{present.length}/{students.length} คน</span>
              </div>
              <div className="progress-bar"><div className="progress-fill" style={{ width:`${pct}%` }} /></div>
            </div>
            <div className="card" style={{ marginBottom:16 }}>
              <div style={{ fontWeight:700, marginBottom:14, fontSize:15 }}>แยกตามหมู่</div>
              {Object.entries(byTroop).map(([troop, d]) => (
                <div key={troop} style={{ marginBottom:12 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", marginBottom:5 }}>
                    <span style={{ fontSize:14 }}>{troop}</span><span style={{ fontSize:13, color:"#94a3b8" }}>{d.present}/{d.total}</span>
                  </div>
                  <div className="progress-bar"><div className="progress-fill" style={{ width:`${d.total?Math.round(d.present/d.total*100):0}%` }} /></div>
                </div>
              ))}
            </div>
            {absent.length>0 && (
              <div className="card" style={{ marginBottom:16 }}>
                <div style={{ fontWeight:700, marginBottom:12, fontSize:15, color:"#f87171" }}>❌ ยังไม่ได้ลงชื่อ ({absent.length} คน)</div>
                <table><thead><tr><th>เลขประจำตัว</th><th>ชื่อ-สกุล</th><th>หมู่</th><th>ชั้น</th><th>ห้อง</th></tr></thead>
                  <tbody>{absent.map(s=><tr key={s.studentId}><td style={{color:"#94a3b8"}}>{s.studentId}</td><td>{s.firstName} {s.lastName}</td><td><span className="tag">{s.troop}</span></td><td>{s.grade}</td><td>{s.room||"-"}</td></tr>)}</tbody>
                </table>
              </div>
            )}
            {present.length>0 && (
              <div className="card">
                <div style={{ fontWeight:700, marginBottom:12, fontSize:15, color:"#4ade80" }}>✅ ลงชื่อแล้ว ({present.length} คน)</div>
                <table><thead><tr><th>เลขประจำตัว</th><th>ชื่อ-สกุล</th><th>หมู่</th><th>ชั้น</th><th>ห้อง</th><th>เวลา</th></tr></thead>
                  <tbody>{present.map(s=><tr key={s.studentId}><td style={{color:"#94a3b8"}}>{s.studentId}</td><td>{s.firstName} {s.lastName}</td><td><span className="tag">{s.troop}</span></td><td>{s.grade}</td><td>{s.room||"-"}</td><td style={{color:"#4ade80",fontSize:13}}>{attendance[s.studentId]?.time}</td></tr>)}</tbody>
                </table>
              </div>
            )}
          </div>
        )}

        {/* ── ADMIN ── */}
        {!loading && view===VIEW.ADMIN && (
          <div>
            {!adminUnlocked ? (
              <div className="card" style={{ maxWidth:380, margin:"40px auto", textAlign:"center" }}>
                <div style={{ fontSize:40, marginBottom:12 }}>🔒</div>
                <div style={{ fontWeight:700, fontSize:18, marginBottom:16 }}>ป้อนรหัสผ่านผู้ดูแล</div>
                <input className="input-field" type="password" placeholder="รหัสผ่าน" value={adminPw}
                  onChange={(e) => { setAdminPw(e.target.value); setPwError(""); }}
                  onKeyDown={(e) => { if(e.key==="Enter"){ if(adminPw===ADMIN_PASSWORD) setAdminUnlocked(true); else setPwError("รหัสผ่านไม่ถูกต้อง"); } }}
                  style={{ marginBottom:10 }} />
                {pwError && <div style={{ color:"#f87171", fontSize:13, marginBottom:10 }}>{pwError}</div>}
                <button className="btn btn-primary" style={{ width:"100%" }} onClick={() => { if(adminPw===ADMIN_PASSWORD) setAdminUnlocked(true); else setPwError("รหัสผ่านไม่ถูกต้อง"); }}>เข้าสู่ระบบ</button>
                
              </div>
            ) : (
              <div>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:20 }}>
                  <h2 style={{ fontSize:20, fontWeight:700 }}>⚙️ จัดการข้อมูล</h2>
                  <button className="btn btn-ghost" style={{ fontSize:13, padding:"6px 12px" }} onClick={() => setAdminUnlocked(false)}>🔒 ล็อค</button>
                </div>

                <div className="card" style={{ marginBottom:16 }}>
                  <div style={{ fontWeight:700, marginBottom:14 }}>📅 ตั้งค่ากิจกรรม</div>
                  <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
                    <div><label style={{ fontSize:13, color:"#94a3b8", display:"block", marginBottom:5 }}>ชื่อกิจกรรม</label>
                      <input className="input-field" value={activityName} onChange={(e) => setActivityName(e.target.value)} /></div>
                    <div><label style={{ fontSize:13, color:"#94a3b8", display:"block", marginBottom:5 }}>วันที่จัดกิจกรรม</label>
                      <input className="input-field" type="date" value={activityDate} onChange={(e) => setActivityDate(e.target.value)} /></div>
                  </div>
                </div>

                <div className="card" style={{ marginBottom:16 }}>
                  <div style={{ fontWeight:700, marginBottom:14 }}>➕ เพิ่มนักเรียนใหม่</div>
                  <div className="add-form-grid">
                    {FIELDS.map(({ key, label }) => (
                      <input key={key} className="input-sm" placeholder={label} value={addForm[key]}
                        onChange={(e) => setAddForm(f => ({ ...f, [key]: e.target.value }))}
                        onKeyDown={(e) => e.key==="Enter" && handleAddStudent()}
                        style={key==="troop"||key==="studentId"?{gridColumn:"1 / -1"}:{}} />
                    ))}
                  </div>
                  {addError && <div style={{ color:"#f87171", fontSize:13, marginBottom:8 }}>{addError}</div>}
                  <button className="btn btn-primary" style={{ fontSize:13, padding:"8px 18px" }} onClick={handleAddStudent}>+ เพิ่มนักเรียน</button>
                </div>

                <div className="card" style={{ marginBottom:16 }}>
                  <div style={{ fontWeight:700, marginBottom:14 }}>📥 นำเข้าจาก Excel</div>
                  <div className={`drop-zone ${dragOver?"over":""}`}
                    onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
                    onDragLeave={() => setDragOver(false)}
                    onDrop={handleFileDrop}
                    onClick={() => fileRef.current.click()}>
                    <div style={{ fontSize:32, marginBottom:8 }}>📁</div>
                    <div style={{ fontWeight:600, color:"#94a3b8" }}>ลากไฟล์มาวางที่นี่ หรือคลิกเพื่อเลือกไฟล์</div>
                    <div style={{ fontSize:13, color:"#475569", marginTop:4 }}>รองรับ .xlsx และ .xls</div>
                  </div>
                  <input ref={fileRef} type="file" accept=".xlsx,.xls" style={{ display:"none" }} onChange={handleFileInput} />
                  {importError && <div style={{ color:"#f87171", fontSize:13, marginTop:10 }}>{importError}</div>}
                  <button className="btn btn-warning" style={{ marginTop:12, fontSize:13 }} onClick={downloadTemplate}>⬇️ ดาวน์โหลดแบบฟอร์มนำเข้า (.xlsx)</button>
                </div>

                <div className="card" style={{ marginBottom:16 }}>
                  <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
                    <div style={{ fontWeight:700 }}>👥 รายชื่อนักเรียน ({students.length} คน)</div>
                    <button className="btn btn-ghost" style={{ fontSize:12, padding:"5px 10px", color:"#f87171" }} onClick={resetAttendance}>🗑️ รีเซ็ตเช็คชื่อ</button>
                  </div>
                  <div style={{ overflowX:"auto" }}>
                    <table>
                      <thead><tr><th>เลขประจำตัว</th><th>ชื่อ</th><th>สกุล</th><th>หมู่</th><th>ชั้น</th><th>ห้อง</th><th>สถานะ</th><th>จัดการ</th></tr></thead>
                      <tbody>
                        {students.map(s => {
                          const isEdit = editingId===s.studentId;
                          return isEdit ? (
                            <tr key={s.studentId} className="edit-row">
                              {["studentId","firstName","lastName","troop","grade","room"].map(k=>(
                                <td key={k}><input className="input-sm" value={editForm[k]}
                                  onChange={(e) => setEditForm(f=>({...f,[k]:e.target.value}))}
                                  onKeyDown={(e) => e.key==="Enter" && saveEdit(s.studentId)} /></td>
                              ))}
                              <td>{attendance[s.studentId]?<span className="badge badge-present">✓ มา</span>:<span className="badge badge-absent">ขาด</span>}</td>
                              <td><div style={{ display:"flex", gap:4 }}>
                                <button className="btn-sm btn-save" onClick={() => saveEdit(s.studentId)}>💾</button>
                                <button className="btn-sm btn-cancel" onClick={() => setEditingId(null)}>✕</button>
                              </div></td>
                            </tr>
                          ) : (
                            <tr key={s.studentId}>
                              <td style={{ color:"#94a3b8" }}>{s.studentId}</td>
                              <td>{s.firstName}</td><td>{s.lastName}</td>
                              <td><span className="tag">{s.troop}</span></td>
                              <td>{s.grade}</td>
                              <td>{s.room||"-"}</td>
                              <td><button className={"btn-sm "+(attendance[s.studentId]?"btn-save":"btn-del")} style={{ minWidth:52 }} onClick={() => toggleAttendance(s)}>{attendance[s.studentId]?"✓ มา":"ขาด"}</button></td>
                              <td><div style={{ display:"flex", gap:4 }}>
                                <button className="btn-sm btn-edit" onClick={() => startEdit(s)}>✏️</button>
                                <button className="btn-sm btn-del" onClick={() => deleteStudent(s.studentId)}>🗑</button>
                              </div></td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
                <button className="btn btn-success" style={{ width:"100%" }} onClick={downloadReport}>⬇️ ดาวน์โหลดรายงานเช็คชื่อ (.xlsx)</button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}
